file.content:
{
  "id": "SPEC-RELEASE",
  "purpose": "Publish every package whose current version is untagged (registry publish, git tag, GitHub release) either locally with `callisto release` or from CI through plan, artifact-manifest and execute, using the merged release PR's committed decision as the only release authority. Every effect is checked against the registry, Git remote or GitHub first, so a rerun finishes a partial release without repeating anything.",
  "scope": "Local `callisto release`, the hidden CI release subcommands, decision verification and source checks, operation order, registry publish and observation, reruns and receipts, tags and GitHub releases and assets, the managed release PR, `[release]` config, and release error codes.",
  "non_goals": [
    "Forges other than GitHub, and publish targets other than crates.io-style Cargo registries, npm and PyPI.",
    "Checking registry credentials before publishing; cargo, npm, twine and gh report their own auth failures.",
    "A workspace lock file; re-observing Git state before every operation guards against concurrent changes.",
    "Persisting execution state between runs; a rerun re-observes providers from scratch.",
    "Apple code signing and notarization of product assets."
  ],
  "api_surface": [
    {
      "name": "callisto release",
      "signature": "callisto [--dry-run] [--format text|json] release [--package ECOSYSTEM/NAME]... [--receipt FILE]",
      "description": "Publishes every untagged package from the current checkout on any branch. With --dry-run it prints the plan and performs no effect.",
      "error_conditions": [
        "Dirty worktree: E051.",
        "Workspace needs the CI route: E239.",
        "Invalid --package: E227, E102 or E169.",
        "Missing or unsafe origin push URL: E132."
      ]
    },
    {
      "name": "callisto release plan (hidden)",
      "signature": "callisto release plan [--source-root DIR] (--from-release-commit SHA --decision FILE | --package ECOSYSTEM/NAME...) [--orchestration-revision SHA --artifact-repository OWNER/REPO] --out FILE",
      "description": "Writes a release plan file (JSON, schemaVersion 5) for a detached source checkout. With --from-release-commit it verifies the committed decision file. With --package it derives the roster from a fresh version plan.",
      "error_conditions": [
        "--dry-run: E217.",
        "Commit verification failure: E165.",
        "[release] present without both orchestration flags: E231."
      ]
    },
    {
      "name": "callisto release build-python (hidden)",
      "signature": "callisto release build-python [--source-root DIR] --intent FILE --artifact-dir DIR",
      "description": "Builds the sdist and wheel of every Python publish in the plan into the directory, without registry credentials.",
      "error_conditions": [
        "--dry-run: E309.",
        "Plan publishes no Python package: E308.",
        "A build with no wheel or no sdist: E306."
      ]
    },
    {
      "name": "callisto release artifact-manifest (hidden)",
      "signature": "callisto release artifact-manifest --intent FILE --artifact-dir DIR [--seal-python] --out FILE",
      "description": "Hashes one regular file per declared artifact slot and writes the artifact manifest. With --seal-python it also records the name, size and sha256 of every built Python file of the plan.",
      "error_conditions": [
        "Plan declares no slots and --seal-python is absent: E219.",
        "--seal-python on a plan that publishes no Python package: E308.",
        "Asset missing, a symlink or not a regular file: E221."
      ]
    },
    {
      "name": "callisto release execute (hidden)",
      "signature": "callisto release execute [--source-root DIR] --intent FILE [--artifact-manifest FILE --artifact-dir DIR] --receipt FILE --orchestration-revision SHA",
      "description": "Validates the plan file against a fresh derivation from the source checkout, runs every operation, and writes the receipt on full success.",
      "error_conditions": [
        "--dry-run: E218.",
        "Stale plan: E124.",
        "Incomplete run: E172."
      ]
    },
    {
      "name": "callisto release inspect (hidden)",
      "signature": "callisto release inspect --input FILE",
      "description": "Prints a plan, artifact manifest or receipt JSON document without recomputing it."
    },
    {
      "name": "callisto release-pr decide | verify | commit-plan",
      "signature": "release-pr decide --snapshot FILE|JSON|- --repository OWNER/REPO --base-branch B --release-branch R; release-pr verify --decision X --snapshot X [--applied-head SHA]; release-pr commit-plan --base-commit SHA --message M [--out FILE]",
      "description": "Decides noop, create or update for the managed release PR from a forge snapshot, re-verifies that snapshot, and builds the commit-API file changes from the staged Git index."
    },
    {
      "name": "callisto version --emit-decision",
      "signature": "callisto version [--no-refresh-lockfiles] --emit-decision PATH",
      "description": "Writes the release decision (package, target version, inclusion reasons) next to the manifest and changelog edits it applies."
    },
    {
      "name": "[release] in callisto.toml",
      "signature": "[release] product-package = \"ECOSYSTEM/NAME\"; forge-repository = \"owner/repo\"; [[release.artifact]] package = \"ECOSYSTEM/NAME\", target = \"TRIPLE\", asset-name = \"FILE\"",
      "description": "Declares the product package, its GitHub repository, and the binary assets attached to its GitHub release.",
      "error_conditions": [
        "No [[release.artifact]], an unqualified package, an unsafe target or asset-name, a duplicate asset-name, or an unsupported profile: E197.",
        "forge-repository missing when planning: E198."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "REL-CMD-01",
      "criterion": "`callisto release` selects every package that has a publish target other than `none` and whose current version has no matching tag, or has a tag on the current commit while any of its operations is not observed already satisfied. For each one it runs the registry publishes, creates the git tag, and creates the GitHub release when `github-release` is a target. A tag on another commit marks the version released without contacting any provider."
    },
    {
      "id": "REL-CMD-02",
      "criterion": "When no package qualifies, `callisto release` prints `Nothing to release.` (JSON: `{\"nothingToRelease\": true}`), exits 0 and runs no command that publishes, pushes or creates anything."
    },
    {
      "id": "REL-CMD-03",
      "criterion": "`callisto release` runs on any branch, leaves HEAD on that branch, and records HEAD's commit as both `releaseSourceRevision` and `orchestrationRevision` in the receipt."
    },
    {
      "id": "REL-CMD-04",
      "criterion": "`callisto release --dry-run` prints each package as `<ecosystem/name> <version>` with its operations (a table on a colour terminal, `Release plan:` lines otherwise) and performs no effect. This holds on a dirty worktree, without an `origin` remote, and in a workspace that needs the CI route. With `--format json` it prints the plan document, whose `digest` equals the receipt's `intentDigest` from a following `callisto release` on the same state; the document carries a sibling `diagnostics` array (e.g. an artifact owner selected without its product) when derivation raised any, and omits the field otherwise. `release plan`'s JSON output carries the same `diagnostics` array; the `--out` file it writes never does."
    },
    {
      "id": "REL-CMD-05",
      "criterion": "Without an `origin` push URL, `--dry-run` prints one stderr note that tag operations are unbound, and `callisto release` fails with E132 before any effect.",
      "is_error_case": true
    },
    {
      "id": "REL-CMD-06",
      "criterion": "A tracked modification or an untracked file not covered by `.gitignore` makes `callisto release` fail with E051 naming a clean worktree and the offending path, before any effect. Ignored files never count.",
      "is_error_case": true
    },
    {
      "id": "REL-CMD-07",
      "criterion": "Repeated `--package <ecosystem/name>` limits the run to the named packages plus every package that shares a `fixed` or `linked` group with one of them."
    },
    {
      "id": "REL-CMD-08",
      "criterion": "A malformed `--package` value fails with `E227` and an unknown package with E102. A duplicate selection, a version whose release is complete, or a package with no publish target fails with E169.",
      "is_error_case": true
    },
    {
      "id": "REL-CMD-09",
      "criterion": "Suppose a selected package has a runtime, optional or peer dependency on a publishable workspace package whose current version is untagged, and that package is not selected. Planning fails with E169 (\"select it too\") before any effect. A dependency whose current version is already tagged need not be selected.",
      "is_error_case": true
    },
    {
      "id": "REL-CMD-10",
      "criterion": "In a workspace with `[[release.artifact]]` slots or a napi/maturin platform package, `callisto release` fails with `E239` before any effect. The help names `release plan`, `release artifact-manifest` and `release execute`.",
      "is_error_case": true
    },
    {
      "id": "REL-CMD-11",
      "criterion": "On success, text output is `Released N package(s)`, followed by `; receipt saved to <path>` when `--receipt` is given, and JSON output is the receipt. A receipt file is written only to the `--receipt` path, never into the checkout, and an unwritable `--receipt` path fails the run before any effect."
    },
    {
      "id": "REL-CMD-12",
      "criterion": "`--format json` output of `release`, `release --dry-run`, `release plan`, `release execute` and `release artifact-manifest` goes through the same envelope every other command's JSON report uses: a top-level `schemaVersion`, `command` (the subcommand name) and `dryRun`, alongside that subcommand's own payload fields unchanged. The intent and artifact-manifest --out files, receipt --receipt file and version --emit-decision file use their durable document shape without command or dryRun wrapper fields."
    },
    {
      "id": "REL-AUTH-01",
      "criterion": "`release plan --from-release-commit <sha> --decision <path>` takes the package and version roster from the decision file committed in that commit. It does not re-run changeset, group, cascade or pre-release selection."
    },
    {
      "id": "REL-AUTH-02",
      "criterion": "`release plan --from-release-commit` fails with E165 and writes no output file in any of these cases: HEAD is not the given commit; the commit neither adds nor modifies the decision file; it deletes no direct-child changeset `.md` file (nested Markdown files and `README.md` do not count); a claimed package's manifest does not change to its claimed version; a claimed package's changelog is unchanged; an unclaimed manifest version changes; or a claimed package is not found.",
      "is_error_case": true
    },
    {
      "id": "REL-AUTH-03",
      "criterion": "A committed decision file whose digest does not match its entries fails with E166. Each target version is parsed using the grammar of its package ecosystem; durable operation IDs, artifact slots and registry observations bound to an operation use that same grammar. Version values remain strings on the wire, and decision schema versions 1 and 2 are accepted; any other version fails with an error naming the version found.",
      "is_error_case": true
    },
    {
      "id": "REL-AUTH-04",
      "criterion": "An abbreviated or unknown `--from-release-commit` SHA, a non-40-hex `--orchestration-revision` for a source with `[release]`, or an `--intent` file with a different `schemaVersion` (`E215`, naming found and expected versions) fails before any output file is written or any effect runs.",
      "is_error_case": true
    },
    {
      "id": "REL-AUTH-05",
      "criterion": "`release plan` and `release execute` require the source checkout at a detached HEAD and fail with E170 otherwise. `callisto release` accepts an attached HEAD. Every route requires a complete, non-shallow SHA-1 repository and fails with E051 otherwise.",
      "is_error_case": true
    },
    {
      "id": "REL-AUTH-06",
      "criterion": "`release execute` re-derives the plan from the source checkout and fails with E124 before any effect when the result differs from the `--intent` file. A change to the decision, source commit, manifests, config, registry binding or origin remote is enough.",
      "is_error_case": true
    },
    {
      "id": "REL-AUTH-07",
      "criterion": "Before each operation, the executor re-checks HEAD, worktree cleanliness and the `origin` push URL. A change stops the run before that operation's effect, with E124 for a moved HEAD or remote and E051 for a dirty worktree.",
      "is_error_case": true
    },
    {
      "id": "REL-AUTH-08",
      "criterion": "`release plan` for a source with `[release]` requires `--orchestration-revision` and `--artifact-repository` (`E231`). For a source without `[release]` it ignores both flags, prints a notice, and plans zero artifact slots.",
      "is_error_case": true
    },
    {
      "id": "REL-AUTH-09",
      "criterion": "`[release].forge-repository` is the only GitHub destination. Planning rejects an `--artifact-repository` that differs from it (`E230`) or from the `origin` GitHub repository (E175). Execution rejects artifact slots that target another repository, and a `[release]` section without it fails planning with E198.",
      "is_error_case": true
    },
    {
      "id": "REL-ORD-01",
      "criterion": "A graph package has one tag, GitHub release draft and publish, however many ecosystems it publishes to. Its tag is created only after all selected registry publishes belonging to its canonical manifests succeed, in every ecosystem a dual Cargo and npm package publishes to, and its GitHub release draft only after its tag. A `[[release.artifact]]` slot's upload follows the product's draft and gates the product's publish even when a different selected package owns the asset, and the release is published only after the draft and every upload."
    },
    {
      "id": "REL-ORD-02",
      "criterion": "A selected package publishes after the selected packages it depends on through runtime, build, optional or dev edges. A dev edge between two packages in the same dependency cycle does not order them, and a runtime, build or optional cycle fails with E104."
    },
    {
      "id": "REL-ORD-03",
      "criterion": "An npm package with attached platform packages publishes each platform package with `npm publish <platform-dir>` before publishing the owner package. Operations run one at a time and the first failure stops the run, so an owner package is never published after one of its platform packages fails."
    },
    {
      "id": "REL-PUB-01",
      "criterion": "Cargo publish runs `cargo publish --manifest-path <pkg>/Cargo.toml --locked` from the workspace root, adding `--registry <key>` for registries other than crates.io. It runs only after the on-disk version (resolving `version.workspace = true`) equals the planned version and fails with an on-disk version drift error otherwise."
    },
    {
      "id": "REL-PUB-02",
      "criterion": "npm publish picks its tool from the workspace that owns the package and runs there. The owner is the nearest directory at or above the package whose `package.json` declares `workspaces` or that has a `pnpm-workspace.yaml`, else for a package no workspace declares the nearest directory with a lockfile, else the root; a lockfile beside a package never moves it out of a declared workspace. The `npm view` observation and a publish by directory run in that same directory, so one `.npmrc` governs what is looked for and what is published. A marker that cannot be inspected is an error, not `npm`. `pnpm-workspace.yaml` alone means pnpm. The tools: `pnpm publish --filter=<name> --no-git-checks`, `yarn workspace <name> npm publish`, `bun publish` in the package directory, and otherwise `npm publish --workspace=<name>`. It appends `--tag next` for prerelease versions and `--access` and `--registry` when set."
    },
    {
      "id": "REL-PUB-03",
      "criterion": "A scoped npm package (`@scope/name`) with no configured access publishes with `--access public`. A configured access value always wins, and an unscoped package with no configured access gets no `--access` flag."
    },
    {
      "id": "REL-PUB-04",
      "criterion": "PyPI publish builds with `python3 -m build --sdist --wheel --outdir <temporary directory>` in the package directory, falling back to `python` and failing with E170 when neither is on PATH, and fails with E306 when the build produced no wheel or no sdist for the version. It then runs `twine upload` naming only the built files the index lacks, with `--repository-url` for a configured upload endpoint (a registry's `publish-url`, else its `url`) and never `--skip-existing`. One build serves the preflight and the publish of a run. Every build runs with `SOURCE_DATE_EPOCH` set to the release commit's committer time. `release build-python` runs the same build for each Python publish of a plan into `--artifact-dir`."
    },
    {
      "id": "REL-PUB-05",
      "criterion": "A `publishConfig.registry` in package.json that does not match the `url` of an npm-kind `[registries]` entry fails with E120. A registry URL that is not `https`, or has userinfo, a query or a fragment, fails with E126. An `origin` push URL that is not HTTPS or `git@` SSH, or that carries credentials, fails with E132. All three fail before any effect.",
      "is_error_case": true
    },
    {
      "id": "REL-PUB-06",
      "criterion": "Cargo observation runs `cargo --config net.retry=0 info NAME@VERSION --registry <name>` from the workspace root, passing `crates-io` for the default. Exit 0 with a matching `version:` line means present, exit 101 with ``could not find `NAME@VERSION` `` means absent, and anything else is indeterminate."
    },
    {
      "id": "REL-PUB-07",
      "criterion": "npm observation runs `npm view NAME@VERSION --json --fetch-retries=0`, with `--registry` when configured. Exit 0 with output means present. A failure whose npm error code is E404, read from the JSON error body on stdout or else from the `code` line on stderr, means absent. Exit 0 with no output, and any other failure, leave the observation indeterminate and are never read as absence."
    },
    {
      "id": "REL-PUB-08",
      "criterion": "PyPI observation fetches `<index>/<normalized-name>/` (the registry's `url`, default `https://pypi.org/simple`; never its `publish-url`) with `curl` and `Accept: application/vnd.pypi.simple.v1+json`. In a 200 JSON body, any matching yanked file means absent; otherwise at least one matching non-yanked file means present. That version-level read serves every use outside an effect. Before a PyPI effect, `release execute` proceeds without a build when the index has no file of the version. Otherwise it builds, and treats the release as already satisfied only when every built file is on the index by filename and not yanked. A built file the index holds yanked is a remote conflict, and a file the index holds that the build did not produce is reported with a warning and not checked. After an upload, confirmation waits for every built file to be visible, and a file this run uploaded must carry the sha256 the index serves for it, or the run fails with E307. A file from an earlier attempt is matched by name, not by digest, unless the artifact manifest seals the release's files: then the run builds nothing, uploads those exact files, compares the sha256 of every file the index holds under a sealed name, and fails with E307 before any upload when one differs. A 404 or no matching file means absent, and a non-JSON body or other non-retryable status is indeterminate. Transient HTTP statuses use the observation retry policy."
    },
    {
      "id": "REL-PUB-09",
      "criterion": "After a publish command reports success, Callisto re-observes the registry and treats \"absent\" as not yet propagated, retrying within the observation limit. A publish whose version the registry never shows fails with E157, including one whose output says the version already exists, and no receipt is written.",
      "is_error_case": true
    },
    {
      "id": "REL-PUB-10",
      "criterion": "Read-only observations (registry query, GitHub release lookup, `git ls-remote`) run at most 5 attempts with exponential backoff from 2 s, capped at 300 s. HTTP 429, 5xx, rate-limited 403 and failed commands are retried, and an observation still indeterminate fails with E176 before that operation's effect.",
      "is_error_case": true
    },
    {
      "id": "REL-PUB-11",
      "criterion": "A publish command that fails with auth, rate-limit or other registry output fails the run with E163. A failing git or gh effect command fails with E164. No effect command is re-issued automatically.",
      "is_error_case": true
    },
    {
      "id": "REL-PUB-12",
      "criterion": "A `pypi` `[registries]` entry may set `publish-url`, the endpoint Twine uploads to when the index at `url` is not also the upload route. Both endpoints follow the registry URL rules of REL-PUB-05 and both enter the registry binding, so changing either makes an earlier intent stale. A package-level `publish-to` index names both routes and overrides the entry's `publish-url`. A `publish-url` on a registry that is not `pypi` is rejected when the configuration loads."
    },
    {
      "id": "REL-RERUN-01",
      "criterion": "An operation whose result is already present and identical is recorded as already satisfied, and its effect is not repeated. For a registry version, stderr shows `warning: <package> <version> is already published; skipping`. During `release execute`, a Python release is satisfied only when every file its build produces is on the index, so a rerun after a partial upload uploads only the missing files. The check that finds a tagged package still to finish reads the version-level answer and does not build."
    },
    {
      "id": "REL-RERUN-02",
      "criterion": "After a run fails partway, rerunning the same command with no state file from the failed run performs only the missing operations and writes a receipt. A local annotated tag on the expected commit that is missing on the remote is pushed before the receipt is written, regardless of its annotation text. `Nothing to release.` is reported only when every operation of every package tagged on the current commit is observed already satisfied. A failure to read the local tag state other than the tag being missing stops the run with an error before any effect."
    },
    {
      "id": "REL-RERUN-03",
      "criterion": "Any of these fails with E167 and is never adopted: a local or remote tag on another commit, a lightweight tag, a GitHub release with a different prerelease flag, an asset of the same name with a different size or sha256, or two assets with the same name. A tag's identity is its target commit plus being annotated; annotation text is never compared.",
      "is_error_case": true
    },
    {
      "id": "REL-RERUN-04",
      "criterion": "A receipt is written only when every operation ends `published` or `alreadySatisfied`, and otherwise the run exits 1 with no receipt file (E172 when operations remain incomplete). The receipt records `intentDigest`, the envelope (`orchestrationRevision`, `releaseSourceRevision`, intent and artifact-manifest digests), and each operation's outcome and provider evidence.",
      "is_error_case": true
    },
    {
      "id": "REL-RERUN-05",
      "criterion": "`workflow_dispatch` with `release_source_sha` releases that commit using the current workflow run's commit as the orchestration revision. The SHA must be 40 lowercase hex characters, resolve to that same commit, and be a GitHub-verified commit merged into `main` from `callisto/version-packages` or `callisto/version-packages--<40-hex>` in the same repository. A recovery run skips `verify` and `version-pr` and is gated by `recovery-checks`."
    },
    {
      "id": "REL-RERUN-06",
      "criterion": "A tag push that GitHub refuses because the tagged commit's workflows differ from every branch tip fails with E180, naming the tag and target commit.",
      "is_error_case": true
    },
    {
      "id": "REL-GH-01",
      "criterion": "Every package with a publish target gets an annotated, unsigned tag named by its tag template, with message `Release <tag>`, on the source commit, pushed to the `origin` push URL."
    },
    {
      "id": "REL-GH-02",
      "criterion": "A package that targets `github-release` gets `gh release create <tag> --repo <owner/repo> --verify-tag --draft`, adding `--prerelease` for prerelease versions. After all its assets upload, the release is published with `gh release edit <tag> --draft=false`."
    },
    {
      "id": "REL-GH-03",
      "criterion": "Release notes are the body of the package CHANGELOG section for the version, passed with `--notes-file`. With no changelog configured, a missing file, or a missing or empty section, Callisto passes `--generate-notes` and prints `notes: using generated notes (<reason>) for <package>` to stderr. A changelog that exists but cannot be read (a permission error, a directory, bytes that are not UTF-8) fails release planning with E125 naming the file, because generated notes would silently replace what the release PR reviewed."
    },
    {
      "id": "REL-GH-04",
      "criterion": "Each `[[release.artifact]]` becomes one upload named `asset-name` on the product package's GitHub release, tagged with the product's own tag and prerelease flag regardless of the asset owner package's version. An artifact whose `package` is not in the release fails with E179, and a `product-package` that is missing or does not target `github-release` fails with E197. When an artifact's owner package is selected but the product package is not, Callisto warns on stderr, records a `product-artifact-owner-without-product` diagnostic (surfaced in `--format json`; see REL-CMD-04), and derives no slot for that asset.",
      "is_error_case": true
    },
    {
      "id": "REL-GH-05",
      "criterion": "`release artifact-manifest` requires, for each slot, a regular non-symlink file named `asset-name` directly in `--artifact-dir` (`E221` for a symlink or non-file, an I/O error when missing) and records its sha256 and byte length. With slots, `release execute` requires both `--artifact-manifest` and `--artifact-dir` (`E233`); without slots it rejects either flag (`E232`) unless the manifest seals Python files. `--seal-python` records the wheel and sdist of every Python publish of the plan, sealed all or none, each named for its package and version, and `release execute` verifies each file's sha256 and byte length (`E139`) before any effect.",
      "is_error_case": true
    },
    {
      "id": "REL-GH-06",
      "criterion": "Before any effect, `release execute` fails with E139 when an artifact's bytes differ from the manifest. It fails with E140 unless `gh attestation verify` passes with the configured `--repo`, `--signer-workflow <repo>/.github/workflows/callisto-release.yml`, `--signer-digest` set to the orchestration revision, `--source-digest` and `--deny-self-hosted-runners`.",
      "is_error_case": true
    },
    {
      "id": "REL-GH-07",
      "criterion": "In the release workflow, `CARGO_REGISTRY_TOKEN` reaches only the `execute` job's execute step. The workflow's default permissions are empty, and the plan and build jobs receive no registry credential."
    },
    {
      "id": "REL-GH-08",
      "criterion": "Callisto finds a GitHub release by tag, draft or published, with the GraphQL `release(tagName:)` lookup followed by `GET /repos/{owner}/{repo}/releases/{id}`; it never reads the release list. After its own release create, asset upload or publish, a release or asset still absent is looked up again with 2s, 4s, 8s, 16s and 32s waits before the run fails with E167."
    },
    {
      "id": "REL-PR-01",
      "criterion": "`release-pr decide` returns `noop` when there are no pending changesets. It returns `update` when one open PR from the same repository has head `<release-branch>` or `<release-branch>--<40 lowercase hex>`, and `create` otherwise."
    },
    {
      "id": "REL-PR-02",
      "criterion": "`release-pr decide` fails in these cases: an invalid repository (E141), an unsafe branch name (E142), duplicate PR numbers (E143), a snapshot for another repository or base branch (E144), a managed-branch PR from a fork (E145), more than one managed PR (E146), a malformed SHA suffix (E147), or a PR headed at `<release-branch>--staging` (E154). Each of these carries its own code even when `--snapshot`/`--decision` is a file, inline JSON, or stdin. `release-pr verify` accepts either the bare decision wire or unchanged `release-pr decide --format json` output through all three input forms. Report metadata, when present, contains both `command: release-pr decide` and boolean `dryRun`; unknown or duplicate fields and malformed, partial or null metadata fail with E281. Nested domain validation retains its typed diagnostic. Verification exits 0 when a fresh snapshot equals the decision's snapshot and fails with E148 otherwise.",
      "is_error_case": true
    },
    {
      "id": "REL-PR-03",
      "criterion": "`release-pr commit-plan` resolves the repository root with `git rev-parse --show-toplevel`, so it works from any subdirectory of the checkout, and emits base64 additions and deletions for the index staged against `--base-commit`. Each added or modified file's content is verified against the index blob sha before it is emitted; a worktree file edited again after staging fails the read (E059) rather than emitting content that does not match what is staged. It fails for: no changes (E149); a mode other than 100644 (E150); a type change or unmerged path (E151); over 4 MiB of content (E152); or a path under `.github/workflows/` or `.git/`, an absolute path, or one containing `..` (E153).",
      "is_error_case": true
    },
    {
      "id": "REL-PR-04",
      "criterion": "The release-PR action runs the version command with `--emit-decision <decision_path>` (default `.callisto/release-decision.json`). It commits the result with GitHub's `createCommitOnBranch` on `<release-branch>--staging` reset to the base commit, and refuses unless the remote tree equals the locally staged tree. It then moves the release branch ref through the REST API and never runs `git push`. Before creating the commit, before moving the ref, and before any label or PR write, it runs `callisto release-pr verify` against a fresh snapshot and stops when verification fails. After an update ref move is read back successfully, the final check supplies `--applied-head <new_sha>`. This accepts only a consistent update decision's selected PR changing to that exact head; any other snapshot change, wrong applied head, or create/noop use fails E148. The final check is retried for up to 27 seconds while the PR list still shows the old head, because the forge can lag a ref move; a head that never shows the applied commit still fails E148. Checks before the move and the create path retain strict original-snapshot equality."
    },
    {
      "id": "REL-PR-05",
      "criterion": "`callisto-action` with `mode: release` runs `callisto --format json release --receipt <tmp>` and sets `published` and `publishedPackages` from registry and platform publish operations whose outcome is `published`. A `mode` other than `version-pr` or `release` fails the step."
    },
    {
      "id": "REL-PR-06",
      "criterion": "With `source: auto`, `callisto-action` and `setup-callisto` default `version` input `latest` installs the callisto release the action's own invocation is pinned to (`github.action_ref` resolved against `orin-dx/callisto`'s `callisto@` tags), falling back to the newest published release only when that ref is unset or matches no tag. An explicit `version` input overrides this resolution, including inside a Callisto checkout. A consumer manifest mentioning callisto-cli never selects a local build. `source: local` ignores version pins and requires Git-tracked Callisto source at the checkout root plus Cargo metadata confirming the local callisto-cli workspace member, manifest path and callisto binary target. Local builds use explicit manifest and output-directory paths; invalid local source fails without falling back to a downloaded or registry installation."
    },
    {
      "id": "REL-PR-07",
      "criterion": "`--format json` output of `release-pr verify`, `release-pr decide` and `release-pr commit-plan` (without `--out`) goes through the same envelope every other command's JSON report uses: a top-level `schemaVersion`, `command` and `dryRun`, alongside that subcommand's own payload fields unchanged. `release-pr verify --decision` accepts `release-pr decide --format json` output as-is."
    },
    {
      "id": "REL-ERR-01",
      "criterion": "Every release failure exits 1 with a diagnostic carrying an `E####` code."
    },
    {
      "id": "REL-ERR-02",
      "criterion": "`--dry-run` with `release plan`, `release artifact-manifest` or `release execute` fails with `E217`, `E216` or `E218` and writes nothing.",
      "is_error_case": true
    },
    {
      "id": "REL-ERR-03",
      "criterion": "A `[release]` section fails config loading with E197 when it has no `[[release.artifact]]`, an unqualified `product-package` or artifact `package`, an unsafe `target` or `asset-name`, or a duplicate `asset-name`. It also fails for a `[release.profiles.<name>]` other than `production`, or a `production` forge-repository that conflicts with the top-level key.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/release.json"
}

{
  "id": "SPEC-VERSIONING",
  "purpose": "Define how `callisto version`, `pre` and `snapshot` turn pending changesets and commits into new package versions, dependency rewrites, changelog sections and an optional release decision file.",
  "scope": "Changeset file format, severity aggregation and commit inference, dependency cascade, fixed and linked groups, prerelease and snapshot versions, and applying the plan to disk.",
  "non_goals": [
    "Creating changesets interactively with `callisto add`.",
    "Publishing, tagging, and verifying a committed release decision during `release`.",
    "Package discovery, workspace config parsing and dependency graph construction.",
    "Release PR body composition."
  ],
  "api_surface": [
    {
      "name": "callisto version",
      "signature": "callisto version [--strict] [--allow-empty-changesets] [--no-refresh-lockfiles] [--emit-decision <PATH>] [--dry-run]",
      "description": "Computes the version plan from pending changesets, inference, cascade and groups, then applies it to disk and stages it in git."
    },
    {
      "name": "callisto pre",
      "signature": "callisto pre enter <TAG> | callisto pre exit",
      "description": "Enters or exits prerelease mode by writing `.changeset/pre.json`."
    },
    {
      "name": "callisto snapshot",
      "signature": "callisto snapshot --tag <TAG> [--strict] [--dry-run]",
      "description": "Sets every package to a throwaway native-grammar snapshot version without consuming changesets: `0.0.0-{tag}-{sha7}` for SemVer and `0.0.0.dev0+{tag}.{sha7}` for PEP 440."
    }
  ],
  "acceptance_criteria": [
    {
      "id": "VER-CS-01",
      "criterion": "A changeset is a Markdown file whose line 1 is `---`, followed by one `name: severity` entry per line, a closing `---` line and a free-text summary; blank lines and lines starting with `#` inside the frontmatter are ignored. Severities are `major`, `minor`, `patch` and `none` (ordered none < patch < minor < major), read case-insensitively and written lowercase."
    },
    {
      "id": "VER-CS-02",
      "criterion": "A package name may be double-quoted, and a quoted name may contain `:` (`\"maven/org.example:foo-core\": major` parses as that name with severity major); an unquoted name is split at its last `:`."
    },
    {
      "id": "VER-CS-03",
      "criterion": "A leading UTF-8 BOM is ignored, CRLF and CR line endings parse the same as LF, the summary is trimmed of surrounding whitespace, and a changeset with a summary but no entries is valid."
    },
    {
      "id": "VER-CS-04",
      "criterion": "Parsing fails with E040 when line 1 is not `---`, E041 when the frontmatter is never closed, and E055 when there are entries but the summary is empty or whitespace-only. A changeset with no entries and no summary (the shape `@changesets/cli add --empty` writes) parses as a valid, empty changeset.",
      "is_error_case": true
    },
    {
      "id": "VER-CS-05",
      "criterion": "Parsing fails on a bad entry line and reports its line number: unclosed quoted name (E042), text between a quoted name and its `:` (E043), no `:` (E044), empty name (E045), unknown severity (E046), or a name already used in the same file (E047, also citing the first line).",
      "is_error_case": true
    },
    {
      "id": "VER-CS-06",
      "criterion": "Writing a changeset emits `---`, one `name: severity` line per entry in order, `---`, a blank line, the trimmed summary and a trailing newline; a name is quoted when it starts with a YAML-significant character (such as `@`, `-`, `#`, `\"` or a space), contains `:` or `#`, or ends with a space."
    },
    {
      "id": "VER-CS-07",
      "criterion": "Writing fails for an empty summary (E049 with no entries, E056 with entries), an empty package name (E057), or a name containing `\"`.",
      "is_error_case": true
    },
    {
      "id": "VER-CS-08",
      "criterion": "`version` reads every `.md` file directly inside the configured changesets directory (default `.changeset`) except `README.md`, in path order; a missing directory means no changesets, and one unparsable file aborts the run with an error naming that file.",
      "is_error_case": true
    },
    {
      "id": "VER-AGG-01",
      "criterion": "A package's severity is the highest severity among all changeset entries naming it and its inferred severity."
    },
    {
      "id": "VER-AGG-02",
      "criterion": "An entry name resolves to a workspace package by prefixed id (`cargo/foo`) or bare name; a bare name that matches packages in two or more ecosystems aborts the run with an ambiguous-name error (E103).",
      "is_error_case": true
    },
    {
      "id": "VER-AGG-03",
      "criterion": "An entry naming a package not in the workspace, or an invalid name, produces an unknown-package warning, and a changeset with any such unresolved entry stays on disk unconsumed, even when its other entries resolve. An entry with severity `none` causes no bump and no changelog line, but its changeset is still consumed."
    },
    {
      "id": "VER-AGG-04",
      "criterion": "Commit inference runs only for packages with `release-trigger = \"auto\"`; packages with the default `release-trigger = \"changeset\"` take severity from changesets alone. Inference reads conventional commits touching the package's directory since its last release tag (all history when untagged): a `!` marker or `BREAKING CHANGE`/`BREAKING-CHANGE` footer maps to major, `feat` to minor, `fix`/`perf`/`revert` to patch, anything else to none."
    },
    {
      "id": "VER-AGG-05",
      "criterion": "`pre-major-inference` changes only inferred severity, and only for a package with a prior release tag whose current version is `0.y.z` with y >= 1: `conservative` maps major to minor, `conservative-feat` also maps minor to patch, and `off` (default) changes nothing."
    },
    {
      "id": "VER-AGG-06",
      "criterion": "When no changeset is consumed, `version` warns \"No pending changesets found in workspace\" unless `--allow-empty-changesets` or `[validation] allow-empty-changesets = true` is set; with `--strict` the warning is an error and `version` exits with a failure status.",
      "is_error_case": true
    },
    {
      "id": "VER-CAS-01",
      "criterion": "When a package is bumped, each dependent's spec on it is tested against the new version. Under `[cascade] mode = \"out-of-range\"` (default) a runtime, optional, build or peer dependent is bumped only when its spec no longer covers the new version; under `mode = \"always\"` it is bumped regardless. Coverage governs only the dependent's own severity bump; whether its spec is rewritten follows VER-CAS-06."
    },
    {
      "id": "VER-CAS-02",
      "criterion": "A cascaded bump has severity `bump-severity` (`patch` default, or `minor`), never lowers a severity the dependent already has, and propagates to that dependent's own dependents."
    },
    {
      "id": "VER-CAS-03",
      "criterion": "With `peer-escalation = true` (default), a peer dependent whose spec no longer covers a minor or major bump of its dependency receives a major bump; a patch bump of the dependency cascades at `bump-severity`."
    },
    {
      "id": "VER-CAS-04",
      "criterion": "A dev dependent is never bumped by the cascade, but its spec is still rewritten when it no longer covers the new version."
    },
    {
      "id": "VER-CAS-05",
      "criterion": "Coverage: an exact spec covers only the equal version, a bare Cargo version is a caret requirement, a caret requirement never covers a prerelease, a Cargo `workspace = true` spec is tested using the root `[workspace.dependencies]` spec, and an npm `workspace:` shorthand (`workspace:`, `workspace:*`, `workspace:^` or `workspace:~`) always covers. A pnpm `workspace:` explicit range or exact version is tested using npm SemVer rules; an alias uses the range after its final `@`, and a relative path binds only to the admitted npm member at that directory. A catalog or other untestable spec is treated as covering and never rewritten; a catalog spec emits a CatalogSpecNotRewritten warning."
    },
    {
      "id": "VER-CAS-06",
      "criterion": "A spec that no longer covers the new version is rewritten to it, keeping the operator and precision for Cargo and npm (`^1.2` becomes `^2.0` for 2.0.0), or to the exact version for npm when `preserve-npm-ranges = false`. A runtime, optional, build or peer dependent that is itself released in this run, for any reason, has every such spec on a bumped internal dependency raised to the dependency's new version the same way, even when the spec still covers it; a dependent that is not releasing keeps its spec unless out of range. `workspace = true`, pnpm rolling `workspace:` shorthands and catalog specs are never rewritten by either rule; an out-of-range pnpm explicit range is rewritten while retaining its `workspace:` protocol and alias. A dev dependent's spec is rewritten only when out of range. A spec that cannot be rewritten mechanically, such as an npm range with spaces, `||`, a hyphen or a wildcard, is left unchanged with a RangeNotRoundTrippable warning."
    },
    {
      "id": "VER-CAS-07",
      "criterion": "A rewrite uses the source declaration's manifest ecosystem and preserves its declared dependency key or spelling, independent of either package's display prefix. A Cargo dependency's `package` name resolves its native target while edits retain its alias; inherited aliases resolve the declaration in the Cargo workspace that governs the member. Python distribution names match using PEP 503 normalization while edits retain the spelling in the dependency declaration. A Cargo dependency inherited with `workspace = true` is rewritten in the workspace root's `[workspace.dependencies]`, not in the member manifest."
    },
    {
      "id": "VER-CAS-08",
      "criterion": "The cascade aborts with E105 when it does not settle within 4 x (package count) + 1 steps, and with a grammar-mismatch error when a spec and the new version use different version grammars (SemVer vs PEP 440).",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-01",
      "criterion": "All package members of a `[[fixed-group]]` receive the group's highest severity and one shared version, computed the same grammar- and pre-release-aware way as any other bump (VER-PRE-03): the alignment base is the on-disk version of the group's released member (a member with a release tag) if the group has one, otherwise the highest on-disk version among its members, bumped by that severity."
    },
    {
      "id": "VER-GRP-02",
      "criterion": "A fixed group whose released members have different on-disk versions aborts the run with E106, one whose released members use different version grammars (or whose untagged members do) aborts with E107, one whose released member has no on-disk base version aborts with E205, and one with no live member carrying a base version aborts with E206.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-06",
      "criterion": "A computed bump — for a single package or a fixed group's shared target — that would sort behind the version it was bumped from aborts the run with E207 instead of writing the regressed version to disk.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-03",
      "criterion": "When any member of a `[[linked-group]]` is bumped, every member receives the group's highest severity and all members move to the highest version any member's own bump produces (members at 1.4.0 and 2.7.3 with a minor bump both become 2.8.0)."
    },
    {
      "id": "VER-GRP-04",
      "criterion": "A package claimed by two groups is rejected: E109 when the claims use different spellings of the same package, and a group-conflict error when they use the same spelling.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-05",
      "criterion": "An attached platform package, or a fixed-group member naming a platform manifest, is not bumped as a package: when its owner is bumped, the platform manifest gets the owner's new version and the owner's `optionalDependencies` entry for it is pinned to that version. A co-located platform manifest that is also one of the owner's canonical manifests is written once, as part of the owner's own bump."
    },
    {
      "id": "VER-PRE-01",
      "criterion": "`callisto pre enter <tag>` writes `.changeset/pre.json` with `mode` `pre`, the tag, every package's current version under `initialVersions`, keyed by its display id (`foo`, or `cargo/foo` when another ecosystem has a `foo`) and an empty `changesets` list, then stages the file with git; under `--dry-run` it prints the content and writes nothing. For promoted packages, an older bare key is assigned to the unique historical owner at the commit that added pre.json; if no unique owner exists, version fails with E245."
    },
    {
      "id": "VER-PRE-02",
      "criterion": "`pre enter` fails when the tag is empty or whitespace, or when `.changeset/pre.json` exists with mode `pre` (also under `--dry-run`); when it exists with mode `exit`, `pre enter` instead resumes the cycle under the new tag, keeping its recorded `initialVersions` and `changesets`. `callisto pre exit` sets `mode` to `exit` and fails when the file is missing or already in `exit` mode.",
      "is_error_case": true
    },
    {
      "id": "VER-PRE-03",
      "criterion": "In pre mode, a bumped package's version is its `initialVersions` entry bumped by its severity plus `-{tag}.N`, where N starts at 0 and increments while the release part is unchanged (0.1.0 with a minor changeset and tag `beta` gives 0.2.0-beta.0, then 0.2.0-beta.1); PEP 440 packages use `aN` for tags `a`/`alpha`, `bN` for `b`/`beta`, `rcN` for `rc`/`c`/`pre`/`preview` (case-insensitive), and `.devN` for any other tag."
    },
    {
      "id": "VER-PRE-04",
      "criterion": "In pre mode, `version` never deletes a changeset from disk. A changeset whose id is not yet in `pre.json`'s `changesets` list counts toward severity, produces a changelog entry, and has its id added to `changesets`; a changeset whose id is already there still counts toward severity and the prerelease counter (VER-PRE-03) but produces no additional changelog entry. The `allow-empty-changesets`/`--strict` handling from VER-AGG-06 triggers only when no changeset -- new or already recorded -- resolves to a package this run, not merely when nothing new was added."
    },
    {
      "id": "VER-PRE-05",
      "criterion": "After `pre exit`, the next `version` moves every package at a prerelease version to its stable release (0.2.0-beta.1 becomes 0.2.0), consumes and deletes the pending changesets, and deletes `pre.json`."
    },
    {
      "id": "VER-PRE-06",
      "criterion": "A malformed `.changeset/pre.json` (invalid JSON, a missing `mode`, `tag`, `initialVersions` or `changesets` field, a mode other than `pre` or `exit`, or an unparsable version) makes `version` fail with E114 and write nothing; an unreadable file fails with E115.",
      "is_error_case": true
    },
    {
      "id": "VER-PRE-07",
      "criterion": "`callisto snapshot --tag <tag>` sets every workspace package, and every attached platform package and fixed-group platform manifest, to a snapshot version built from the same tag and sha7 (the first 7 characters of HEAD) in the package's own grammar: `0.0.0-{tag}-{sha7}` for a SemVer package, `0.0.0.dev0+{tag}.{sha7}` for a Pep440 package; it fails if HEAD cannot be resolved."
    },
    {
      "id": "VER-PRE-08",
      "criterion": "A snapshot writes manifests and refreshes each active ecosystem's existing lockfile, unconditionally (there is no `--no-refresh-lockfiles` for `snapshot`), so a subsequent locked install resolves against the snapshot version; it ignores and keeps pending changesets, writes no changelog or `pre.json`, and stages nothing in git; under `--dry-run` it writes nothing."
    },
    {
      "id": "VER-PRE-09",
      "criterion": "For every workspace dependency whose current spec does not cover the snapshot version, `snapshot` rewrites that spec using the source declaration's manifest ecosystem and declared key or spelling, including Cargo aliases. Inherited Cargo declarations are rewritten in the root manifest of the Cargo workspace that governs the member rather than the member manifest. A spec that already covers the snapshot version is left unchanged."
    },
    {
      "id": "VER-PRE-10",
      "criterion": "Every `pre.json` initial version is validated using the owning package's native grammar after historical and promoted identity resolution; the original JSON string is validated, not a spelling normalized by a cross-ecosystem fallback. A malformed owned baseline fails with E114 before version, changelog, pre-state or changeset writes during `version`, `pre exit` or resuming with `pre enter`."
    },
    {
      "id": "VER-APPLY-01",
      "criterion": "`version` writes the new version to every canonical manifest of a bumped package, so both manifests of a dual-manifest package move together."
    },
    {
      "id": "VER-APPLY-02",
      "criterion": "Before writing a package or platform manifest, apply reads its current version: equal to the planned `from` it is written, equal to the target it is left unchanged, so applying the same plan again is safe."
    },
    {
      "id": "VER-APPLY-03",
      "criterion": "A manifest whose current version is neither the planned `from` nor the target aborts apply with E117 naming the path, the found version and both expected versions.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-04",
      "criterion": "A manifest that receives a version bump and dependency rewrites in the same run is read once and written once with all changes, and a manifest already at its target with no rewrites is not rewritten. An owner's `optionalDependencies` pins, and edits to a workspace root `Cargo.toml` that is also a package manifest, are written separately."
    },
    {
      "id": "VER-APPLY-05",
      "criterion": "Files are written one at a time, each by atomic replacement, so an interrupted run never leaves a partially written file; a failing write stops the run and leaves earlier files in place. A write also fails when the directory holding the new file cannot be synced, unless the filesystem cannot sync a directory."
    },
    {
      "id": "VER-APPLY-17",
      "criterion": "Before the first write, every file the plan edits, creates or deletes is checked: a manifest must exist as a readable regular file, no path may be a symbolic link or sit beneath one (Git cannot stage it), no path may leave the workspace, the directory of each written file (or its nearest existing parent) must take a new file, and a file the plan stages must not be ignored by a .gitignore unless Git already tracks it. Checking creates no file or directory. Any failure stops the run with E314 naming every such path, and nothing has been written, staged or deleted. A lockfile that a .gitignore ignores is still refreshed on disk but is not staged. The checks cover only what can be known beforehand: a lockfile refresh that fails (E208) or a Git command that fails while staging can still stop the run after the writes.",
      "is_error_case": true
    },
    {
      "id": "VER-READ-01",
      "criterion": "Only a missing file is treated as absent when reading `callisto.toml`, `.changeset/pre.json`, a changelog, or the changeset directory. A file that cannot be read or inspected (a permission error, a directory, invalid UTF-8) fails the command naming the path; a dangling link or an entry removed during listing holds no changeset.",
      "is_error_case": true
    },
    {
      "id": "VER-READ-02",
      "criterion": "Only \"not found\" is treated as absent when callisto asks Git about a tag, ref, path or file content: a tag list, a ref that does not resolve, a path missing at a revision, a search with no match, and a repository with no commits yet each answer \"none\". Any other Git failure (not a repository, a broken repository, a revision that cannot be searched) fails the command naming the Git command and its error. A tag that is listed but does not resolve to a commit fails `status` and `version` instead of widening commit inference to the whole history.",
      "is_error_case": true
    },
    {
      "id": "VER-READ-04",
      "criterion": "Planning fails with E315 in a shallow clone when any package infers its bump from commits (`release-trigger = \"auto\"`), because the commit window would be shorter than the real one. Packages that take their bump from changesets alone are unaffected.",
      "is_error_case": true
    },
    {
      "id": "VER-READ-03",
      "criterion": "`status` reports a tag that matches a package's tag template but is not a valid version as one warning naming the tag, however many packages share the template.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-18",
      "criterion": "A file callisto rewrites keeps its permission bits, and a file it creates gets the mode any new file gets under the process umask."
    },
    {
      "id": "VER-APPLY-06",
      "criterion": "For each bumped package, apply prepends a `## {version}` section under the `# {package}` heading of its changelog (default `CHANGELOG.md` in the package directory, overridable with `changelog`), creating the file if missing and keeping CRLF line endings; a changelog that already has that heading is left unchanged."
    },
    {
      "id": "VER-APPLY-07",
      "criterion": "A changelog section lists each changeset summary as a bullet (continuation lines indented), an inferred bump as a commit subject with its short sha, a group bump as \"Released together with the `{group}` {fixed|linked} group.\", a new fixed-group member as \"Joined the `{group}` group at this version.\", a peer escalation as \"Peer dependency `{dep}` requires `{version}`\", and cascaded bumps as \"`{dep}` → `{version}`\" lines under a \"Dependency updates\" bullet."
    },
    {
      "id": "VER-APPLY-08",
      "criterion": "Outside pre mode, `version` refreshes affected lockfiles and stages written manifests, changelogs, `pre.json` changes and existing lockfiles before consuming release inputs. It stages consumed changeset and `pre.json` deletions via `git rm --cached --ignore-unmatch` before unlinking those files from disk. If refresh, generated-state staging or input-deletion staging fails, changesets and pre-state deletion inputs remain on disk for retry."
    },
    {
      "id": "VER-APPLY-09",
      "criterion": "`version --dry-run` prints the computed plan (text output starts with `[DRY-RUN]`) and writes, deletes and stages nothing."
    },
    {
      "id": "VER-APPLY-10",
      "criterion": "`version --emit-decision <path>` writes the release decision JSON to `<path>` relative to the workspace root after the plan has been applied successfully: `schemaVersion` 2, a digest, and one entry per canonical manifest of each bumped package (ecosystem-qualified name, target version, reasons) sorted by package. Reason `kind` is `changeset`, `inference`, `fixedGroup` or `linkedGroup` (with `groupId`), `cascade` (with source package and edge kind, `peer` for peer escalation) or `preReleasePolicy` (with the prerelease tag)."
    },
    {
      "id": "VER-APPLY-11",
      "criterion": "`--emit-decision` with `--dry-run` is rejected before any work, and a plan with no bumps, or whose group members have different target versions, fails to produce a decision before any file is written.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-12",
      "criterion": "A diagnostic escalated to an error (for example `--strict` on the empty-changeset warning) is evaluated right after planning: `version` writes nothing -- not the manifests and changelog, not `pre.json`, not the `--emit-decision` file -- and exits with a failure status, instead of applying the plan and only then failing.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-13",
      "criterion": "Outside `mode: pre`, after planning but before any write, `version` refuses with E121 when a canonical manifest's on-disk effective version differs from its version at `HEAD`, or when its effective version staged in the git index differs from `HEAD`, provided a changeset remains in the `HEAD` tree or configured working-tree changesets directory (including untracked files), or a canonical manifest is staged. Staged metadata-only edits with unchanged effective versions are allowed. A Cargo package that inherits its version is compared against the workspace it names at `HEAD`, in the index and in the working tree, so a staged bump to the workspace it named at `HEAD` is found even after the working tree names another. During `mode: exit`, already-written prerelease versions may be finalized to stable versions; a changed stable version is not exempt and is refused on retry. This detects interrupted applies without consuming retained inputs or stacking a second bump. E121 directs users to inspect staged and unstaged diffs; when outputs are verified as belonging to an interrupted apply, users finish removing its retained changeset or pre-state input with `git rm -- <path>` and commit, otherwise they commit intended version changes or restore affected files to `HEAD`. A repository with no commits yet, a manifest/changesets directory that didn't exist at `HEAD`, or an active `mode: pre` cycle (which legitimately reruns `version` without a commit in between) is not refused this way.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-14",
      "criterion": "By default, applying a plan refreshes and stages lockfiles for every ecosystem represented by an actual version, dependency, platform or optional-dependency write target, including all manifests of a dual-manifest package and workspace-root Cargo writes. It refreshes each existing lockfile: `cargo update --workspace`, run in the directory of each Cargo workspace written to and refreshing the `Cargo.lock` beside its root manifest, for Cargo; for Pypi, `uv lock` if `uv.lock` exists, else `poetry lock --no-update` if `poetry.lock` exists, else `pdm lock --update-reuse` if `pdm.lock` exists; for Npm, `npm install --package-lock-only --ignore-scripts` for `package-lock.json`, `pnpm install --lockfile-only` for `pnpm-lock.yaml`, `yarn install --mode update-lockfile` for `yarn.lock`, and `bun install --lockfile-only` for `bun.lock` or `bun.lockb`, each independently when its lockfile is present. An npm or Python package's lockfile is the one in the workspace that owns it (the nearest directory at or above it that declares a workspace, else for a package none declares the nearest with a lockfile), and its refresh runs in that directory, so a workspace below the root keeps its own. `--no-refresh-lockfiles` skips refresh; applicable existing lockfiles are still staged."
    },
    {
      "id": "VER-APPLY-15",
      "criterion": "A lockfile refresh command that exits non-zero aborts `version` with E208 naming the lockfile and the exact command that failed, instead of recording the failure and continuing.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-16",
      "criterion": "When E121 checks a staged canonical manifest outside prerelease mode, `version` compares its effective version in the Git index as well as the working tree against `HEAD`. It refuses if either copy contains an uncommitted version change, even when the other copy matches `HEAD`; staged metadata-only changes with the same effective version remain allowed.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/versioning.json"
}

{
  "id": "SPEC-WORKSPACE",
  "purpose": "Define how Callisto finds the workspace root, decides which manifests are packages, gives each package an identity, applies per-package config, and treats npm platform packages.",
  "scope": "Workspace root detection, project discovery and membership, package identity and dependency edges, [[package]]/[[package-set]] resolution, and npm platform packages.",
  "non_goals": [
    "Version planning, changelog and manifest write rules beyond platform version propagation.",
    "Release operation derivation and registry publishing of platform packages.",
    "Fixed and linked group semantics other than naming a platform package as a member.",
    "Ecosystems other than Cargo, npm and Python."
  ],
  "api_surface": [
    {
      "name": "Package key",
      "signature": "Package::key() -> Option<PackageKey>",
      "description": "A package's stable internal identity: the workspace-relative directory of its first canonical manifest. Promotion never changes it. Never printed as a package id.",
      "error_conditions": [
        "`None` only for a package with no canonical manifest, which workspace loading never produces."
      ]
    },
    {
      "name": "Package id",
      "signature": "PackageId = \"<name>\" | \"<ecosystem>/<name>\"",
      "description": "Display and selector form: the bare manifest name, or `<ecosystem>/<name>` once another ecosystem declares the same name. JSON output, messages, changeset entries and `pre.json` keys use it; `<ecosystem>/<name>` and `<ecosystem>:<name>` select the package whether or not it is promoted.",
      "error_conditions": [
        "A bare name shared by promoted packages is E103; a qualified name with no such manifest is E102."
      ]
    },
    {
      "name": "[[package]] match",
      "signature": "match = \"<name>\" | \"<ecosystem>:<name>\" | \"<ecosystem>/<name>\"",
      "description": "Exact package id. Ecosystem prefixes: cargo, npm, pypi.",
      "error_conditions": [
        "An empty, absolute, `..`-containing or otherwise unparseable id fails config loading."
      ]
    },
    {
      "name": "[[package-set]] match",
      "signature": "match = \"<glob>\" | \"<ecosystem>:<glob>\" | \"<ecosystem>/<glob>\"",
      "description": "Glob over package names. The colon and slash forms both scope the glob to an ecosystem; a bare glob matches any ecosystem.",
      "error_conditions": [
        "An invalid glob fails config loading."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "WS-DISC-01",
      "criterion": "Root detection walks up from the start directory, never past the Git toplevel, and picks the nearest directory with a workspace marker (Cargo.toml with a `workspace` table, package.json with `workspaces`, pnpm-workspace.yaml, or a .moon directory); with no marker it picks the outermost directory with a package manifest (Cargo.toml with a `package` table, package.json, or pyproject.toml). A Cargo `workspace` or `package` table counts however it is written: a header, an inline table, dotted keys, or, for `workspace`, a sub-table such as `[workspace.package]` alone."
    },
    {
      "id": "WS-DISC-02",
      "criterion": "Root detection fails with E030 naming the start directory and Git toplevel when no marker or package manifest exists up to the toplevel, and with E058 (help suggests `git init`) when the start directory is not inside a Git repository.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-03",
      "criterion": "Discovery treats every directory under the root whose Cargo.toml, package.json or pyproject.toml parses and declares a package name as a candidate, following symlinks up to 32 levels deep (only so a package found beneath one can be named, see WS-DISC-11) and skipping hidden and gitignored paths and directories named target, node_modules, .git, .moon and dist; a manifest without a name is not a package. A manifest that fails to parse, or that cannot be read (a permission error, a directory, invalid UTF-8), is a coded error naming its path and the cause when the path is admitted by explicit workspace membership or shares a directory with an admitted manifest, otherwise it is a warning naming the path and the cause, and discovery continues without it. Only a package manifest that does not exist is treated as absent."
    },
    {
      "id": "WS-DISC-04",
      "criterion": "A Cargo candidate is admitted when the root Cargo.toml [workspace] has no `members` key or its path matches `members`, and its path does not match `exclude`; Python candidates follow the same rules using pyproject.toml [tool.uv.workspace]. A glob entry written with a leading `./` or a trailing `/` (`./packages/*`, `packages/*/`) names the same directories as without. A workspace nested below the root (Cargo `[workspace]`, npm `workspaces` or `pnpm-workspace.yaml`, uv `[tool.uv.workspace]`) also judges the packages beneath it, through the nearest such workspace, by its own list; the workspace at the root keeps deciding for everything beneath it, and a nested manifest that cannot be read or parsed fails discovery. A private, versionless `package.json` that holds an npm workspace is never a package, at the root or below it."
    },
    {
      "id": "WS-DISC-05",
      "criterion": "Membership globs match root-relative paths where `*` matches one path segment, `**` matches any depth, and an entry starting with `!` removes matching paths from the list's other entries."
    },
    {
      "id": "WS-DISC-06",
      "criterion": "With no root manifest or no workspace table for an ecosystem, every candidate of that ecosystem is admitted; an empty `members`, `workspaces` or `packages` list admits none except a hybrid root."
    },
    {
      "id": "WS-DISC-07",
      "criterion": "An npm candidate is admitted when its path matches the `packages` list of the root pnpm-workspace.yaml, or, when that file is absent, empty or has no `packages` key, the root package.json `workspaces` array; with neither, all npm candidates are admitted."
    },
    {
      "id": "WS-DISC-08",
      "criterion": "A hybrid root (root Cargo.toml with both [package] and [workspace], root pyproject.toml with both [project] and [tool.uv.workspace], or a root package.json with a `name`) is always admitted, even when `exclude` matches `.` or the member globs do not. A root package.json that is both `private` and versionless is never discovered as an npm package (it only holds `workspaces`), regardless of admission."
    },
    {
      "id": "WS-DISC-09",
      "criterion": "Malformed membership input fails discovery with a coded error naming the file and never falls back to admitting every directory: a root Cargo.toml, pyproject.toml, package.json or pnpm-workspace.yaml that cannot be read (E310) or parsed (E209), a `members`, `exclude`, `workspaces` or `packages` value that is not an array of strings (npm `workspaces` may also be an object with a `packages` array), a `[workspace]` that is not a table, a pnpm-workspace.yaml whose top level is not a mapping, a root package.json that is not an object, or an entry that is not a valid glob (E311). A missing manifest, a manifest with no workspace table or no `members`, and an empty or `packages`-less pnpm-workspace.yaml restrict nothing. A leading byte-order mark is ignored.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-10",
      "criterion": "An invalid glob in `members`, `exclude`, `workspaces` or `packages` fails discovery with E311 naming the file; no entry of the list is applied or skipped on its own.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-11",
      "criterion": "A package whose path passes through a symbolic link is a coded error naming the package (E312), because Git cannot stage a path beneath a link and a version bump there could never be committed; a symbolic link that holds no package is ignored, and a link can be ignored through a .gitignore under the workspace root.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-12",
      "criterion": "Locating the workspace root fails with a coded error naming the file when a Cargo.toml or package.json between the start directory and the Git root cannot be read (E310) or parsed (E209), instead of settling on a different root.",
      "is_error_case": true
    },
    {
      "id": "WS-LOAD-01",
      "criterion": "Loading a workspace for `version`, `release` or any command that writes fails with E313, naming each affected manifest once, when the graph build could not open a discovered manifest to read its platform role, publish targets or dependencies; it never continues with those packages omitted. This includes `status`, `add`, `pre`, `matrix`, `snapshot` and `compose-pr-body`.",
      "is_error_case": true
    },
    {
      "id": "WS-LOAD-02",
      "criterion": "A Cargo package belongs to the workspace its `package.workspace` names, else to the nearest `Cargo.toml` at or above its directory, never above the workspace root, that has a `workspace` table (the package itself counts); it need not be the root's. A `version.workspace = true` or `{ workspace = true }` dependency resolves against that workspace's `[workspace.package]` and `[workspace.dependencies]`, and a version or dependency spec rewrite is written to that workspace's manifest. A package that inherits when no such workspace exists, whose `package.workspace` names no workspace or leaves the root, or whose ancestors cannot be read or parsed, fails with E313 naming the package.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-01",
      "criterion": "A package whose name is claimed by no other directory gets a bare id equal to its manifest name (for example `foo` or `@scope/foo`)."
    },
    {
      "id": "WS-ID-02",
      "criterion": "A dual-manifest package (one directory with several admitted manifests) is one package whose id comes from Cargo.toml, else package.json, else pyproject.toml, and each manifest's own name still resolves to that package within its ecosystem -- including through `--package`, `add` and a changeset entry naming the package by a non-primary manifest's own name, not only its primary name."
    },
    {
      "id": "WS-ID-03",
      "criterion": "When two or more directories declare the same name and no ecosystem declares it in more than one of them, each package is promoted to an ecosystem-qualified id, displayed as `cargo/foo`. Promotion preserves the package's key (its workspace-relative directory) and CHANGELOG path; `cargo/foo` selects it in both states. Newly created default tags use `{display id}@{version}`, so promotion changes their namespace. A promoted package's last tag is also found among `foo@*` tags whose commit contains its manifest and no other same-named package's. A bare `pre.json` `initialVersions` key moves to the one same-named package that existed when `pre.json` was added, else `version` fails with E245."
    },
    {
      "id": "WS-ID-04",
      "criterion": "When two directories declare the same name in the same ecosystem (including a dual-manifest Cargo+npm `foo` and an npm-only `foo`), loading fails with E100 naming both paths.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-05",
      "criterion": "A `[[fixed-group]]` or `[[linked-group]]` member written `cargo:foo` or `cargo/foo` resolves to package `foo` when a Cargo manifest declares `foo`, promoted or not, through the same selector resolver used for `--package` and changesets; a member naming an ecosystem with no such manifest fails loading with E108, and a bare member name ambiguous across ecosystems fails loading with E103 (not E108).",
      "is_error_case": true
    },
    {
      "id": "WS-ID-06",
      "criterion": "A changeset, `callisto add --package` or `callisto matrix --package` naming the bare name of promoted packages fails with E103 listing every qualified candidate and showing the qualified form to write; naming a package that does not exist under that name in that ecosystem fails with E102.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-07",
      "criterion": "A dependency edge is created only to a workspace package that declares the dependency's name in the depending manifest's own ecosystem; a name declared only in other ecosystems creates no edge and one `unknown-package` warning listing the candidates (`cargo:foo`), and an ordinary name no workspace package declares creates no edge and no diagnostic. An explicit pnpm `workspace:` reference that cannot resolve to an admitted npm member creates no edge and emits one `unknown-package` warning."
    },
    {
      "id": "WS-ID-10",
      "criterion": "For pnpm dependencies, Callisto preserves the declared key, target distribution name and exact `workspace:` suffix separately. `workspace:`, `workspace:*`, `workspace:^` and `workspace:~` are version-derived shorthands; aliases such as `workspace:foo@^1` resolve `foo` while retaining the declared key; relative references resolve only to the admitted npm member at the resolved directory. Valid npm `||` alternatives are evaluated as a union for dependency coverage, while any invalid alternative makes coverage unknown. Catalog and opaque references are not guessed or rewritten."
    },
    {
      "id": "WS-ID-08",
      "criterion": "A package whose explicit `tag-template` equals another package's default tag template makes `status` and `version` fail with E101 naming both packages and the template.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-09",
      "criterion": "A discovered package whose canonical manifests use different version grammars fails with E007 before version planning or init writes. This includes co-located Cargo.toml and pyproject.toml, whether the Python version is static or declared dynamic; matching numeric version strings do not bypass the grammar check.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-01",
      "criterion": "For each package, the first ecosystem-prefixed `[[package]]` rule whose ecosystem the package actually has a manifest in and whose name matches applies, regardless of declaration order relative to bare rules; a prefixed rule for an ecosystem the package has no manifest in never applies, even to a same-named package in another ecosystem. If no prefixed rule applies, the first matching bare rule applies."
    },
    {
      "id": "WS-CFG-03",
      "criterion": "A bare `[[package]]` rule that would apply to a promoted package fails loading with E103 listing the qualified candidates; prefixed rules for the same packages load normally.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-04",
      "criterion": "A `[[package-set]]` rule applies only when no `[[package]]` rule matches, the first matching set in declaration order wins, and a `cargo:`/`cargo/`, `npm:`/`npm/` or `pypi:`/`pypi/` prefix restricts it to packages with a manifest in that ecosystem."
    },
    {
      "id": "WS-CFG-05",
      "criterion": "A matched rule overrides only the fields it sets; otherwise a package uses release trigger `changeset`, `CHANGELOG.md` in its directory (a configured changelog is relative to the package directory), and the publish targets its manifests declare."
    },
    {
      "id": "WS-CFG-06",
      "criterion": "A `publish-to` override whose target ecosystem is not among the matched package's manifest ecosystems fails loading with E119.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-07",
      "criterion": "A `[[package-set]]` that matches no package emits one `package-set-matched-nothing` warning naming its pattern; a set matching a package that a `[[package]]` rule shadows counts as matched.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-08",
      "criterion": "A bare `[[package]]` rule matching packages whose manifests span two or more ecosystems, such as a dual-manifest package, emits one non-fatal `bare-rule-matches-multiple-ecosystems` warning; prefixed rules and `[[package-set]]` rules never emit it.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-09",
      "criterion": "A `[[package]]` rule that matches no package emits one `package-rule-matched-nothing` warning naming the rule.",
      "is_error_case": true
    },
    {
      "id": "WS-PLAT-01",
      "criterion": "A package.json with non-empty `os` and `cpu` arrays is an npm platform package whose platform and arch are the first entries; for Linux its ABI is `gnueabihf`, `gnu` or `musl` from the name's `-<abi>` suffix, otherwise none."
    },
    {
      "id": "WS-PLAT-02",
      "criterion": "An npm-only platform package named in the `optionalDependencies` of exactly one admitted npm package becomes an attached platform package of that owner, inside or outside the npm workspace globs: it is not its own package and adds no publish targets to the owner."
    },
    {
      "id": "WS-PLAT-03",
      "criterion": "A co-located platform manifest belongs to its directory's package, is never attached to another owner, and a `[[fixed-group]]` member may name any platform manifest by its own npm name."
    },
    {
      "id": "WS-PLAT-04",
      "criterion": "When an owner is versioned or snapshotted, each attached platform manifest receives the owner's new version and the owner's `optionalDependencies` pins update to it, with no fixed group required."
    },
    {
      "id": "WS-PLAT-05",
      "criterion": "An admitted platform package named in no owner's or several owners' `optionalDependencies` stays its own package and emits a `platform-package-without-owner` warning with its manifest path and the owner count or paths.",
      "is_error_case": true
    },
    {
      "id": "WS-PLAT-06",
      "criterion": "A platform package outside the npm workspace named by several owners emits `platform-package-without-owner` stating it is not released; one named by no owner stays undiscovered with no diagnostic.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/workspace.json"
}

{
  "id": "SPEC-CLI",
  "purpose": "Defines the callisto command-line surface a user or CI script sees: commands, global flags, output formats, exit codes, and the behavior of status, add, init, pre, snapshot, completions and schema, plus the release workflow init generates.",
  "scope": "Command surface and help, global flags, text and JSON output, colour, exit codes, status, add, init, generated workflows and callisto-action modes, pre, snapshot, completions, schema.",
  "non_goals": [
    "Release planning, publishing and receipts behind `callisto release` and its hidden subcommands.",
    "Version planning, cascade and changelog rules behind `callisto version`.",
    "The callisto.toml schema beyond the keys init writes.",
    "Managed release-PR decisions made by the hidden `release-pr` plumbing."
  ],
  "api_surface": [
    {
      "name": "add",
      "signature": "callisto add [--package <NAME:SEVERITY>]... [--summary <TEXT>]",
      "description": "Writes one changeset to .changeset/<adjective>-<noun>-<verb>.md, from flags or, with no --package and a terminal stdin, from an interactive wizard.",
      "error_conditions": [
        "No --package and stdin is not a terminal.",
        "--package given without --summary, or with a blank summary.",
        "A --package value without `:severity`, with a severity other than none, patch, minor or major, or naming a package not in the workspace."
      ]
    },
    {
      "name": "status",
      "signature": "callisto status [--check] [--strict]",
      "description": "Shows each package's current version and planned bump, the pending package count, and diagnostics.",
      "error_conditions": [
        "With --check, any error-level diagnostic (after --strict escalation) exits 1."
      ]
    },
    {
      "name": "version",
      "signature": "callisto version [--no-refresh-lockfiles] [--strict] [--allow-empty-changesets] [--emit-decision <PATH>]",
      "description": "Consumes pending changesets and applies the planned version bumps.",
      "error_conditions": [
        "With --strict, no pending changesets exits 1 with an error diagnostic."
      ]
    },
    {
      "name": "pre",
      "signature": "callisto pre enter <TAG> | callisto pre exit",
      "description": "Enters or exits prerelease mode by writing .changeset/pre.json.",
      "error_conditions": [
        "`pre enter` while pre.json's mode is already `pre`.",
        "`pre exit` after prerelease mode was already exited, or with no .changeset/pre.json."
      ]
    },
    {
      "name": "snapshot",
      "signature": "callisto snapshot --tag <TAG> [--strict]",
      "description": "Sets every package's manifest version to a native-grammar snapshot without consuming changesets: 0.0.0-<TAG>-<short HEAD sha> for SemVer, 0.0.0.dev0+<TAG>.<short HEAD sha> for PEP 440.",
      "error_conditions": [
        "--tag missing (usage error, exit 2).",
        "With --strict, error-level workspace graph diagnostics."
      ]
    },
    {
      "name": "init",
      "signature": "callisto init [--yes] [--versioning fixed|independent] [--artifact-target <TRIPLE>[,<TRIPLE>]...] [--product-package <PACKAGE>] [--forge-repository <OWNER/REPO>] [--workflow | --no-workflow]",
      "description": "Detects the workspace, asks only for intent, previews the first release, then writes callisto.toml, .changeset/README.md and optionally .github/workflows/callisto-release.yml.",
      "error_conditions": [
        "callisto.toml already exists.",
        "Not inside a Git repository; without `origin`, only an explicit workflow or artifact request fails.",
        "A package matches more than one tag convention, or more than one package matches `v{version}`.",
        "stdin is not a terminal and --yes is absent; --yes without a required flag.",
        "--workflow together with --no-workflow.",
        "Invalid --artifact-target, --product-package or --forge-repository values.",
        "--workflow when a workflow file already exists or the workspace shape has no generated workflow."
      ]
    },
    {
      "name": "release",
      "signature": "callisto release [--package <ECOSYSTEM/NAME>|<ECOSYSTEM:NAME>]... [--receipt <FILE>]",
      "description": "Publishes every package whose current version is unreleased; with --dry-run prints the release plan only.",
      "error_conditions": [
        "Any planning or publishing failure exits 1; `Nothing to release.` exits 0."
      ]
    },
    {
      "name": "completions",
      "signature": "callisto completions <bash|elvish|fish|powershell|zsh>",
      "description": "Prints a shell completion script to stdout.",
      "error_conditions": [
        "An unsupported shell name (usage error, exit 2)."
      ]
    },
    {
      "name": "schema (hidden)",
      "signature": "callisto schema [--type <TYPE>]",
      "description": "Prints the JSON Schema for a report type (status by default; also version, snapshot, init, changeset, pre-state, matrix, release-receipt). `pre-state` is the on-disk `.changeset/pre.json` file shape, not `pre`'s own `--format json` report.",
      "error_conditions": [
        "An unknown --type is a clap usage error (exit 2) listing the supported values."
      ]
    },
    {
      "name": "help (hidden)",
      "signature": "callisto help [<command>...]",
      "description": "Prints the root help, or a named subcommand's help (nested subcommands accepted as multiple words, e.g. `callisto help pre enter`); fills the role clap's own disabled help subcommand would otherwise have.",
      "error_conditions": [
        "A command name that does not exist exits 1 naming it."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CLI-SURF-01",
      "criterion": "`callisto --help` lists eight commands (add, status, version, pre, snapshot, init, release, completions), each with a one-line description, plus the global options --format, --cwd, --dry-run, --help and --version."
    },
    {
      "id": "CLI-SURF-02",
      "criterion": "`matrix`, `schema`, `help`, `compose-pr-body`, `release-pr`, and `release plan|inspect|build-python|artifact-manifest|execute` are absent from `--help` output but still parse and run when invoked."
    },
    {
      "id": "CLI-SURF-06",
      "criterion": "`callisto help` prints the root help; `callisto help <command>` (nested names accepted as multiple words) prints that subcommand's help; an unknown command name exits 1 naming it. `callisto completions <shell>` never offers a hidden subcommand, at any nesting depth."
    },
    {
      "id": "CLI-SURF-04",
      "criterion": "`--format`, `--cwd` and `--dry-run` are accepted before or after any subcommand name; --format defaults to text and --cwd defaults to the current directory."
    },
    {
      "id": "CLI-SURF-05",
      "criterion": "With --dry-run, add, init, pre, snapshot and version write nothing; text output marks the preview with `[DRY-RUN]`."
    },
    {
      "id": "CLI-OUT-01",
      "criterion": "When stdout is a terminal and NO_COLOR is unset, `status` and `release --dry-run` render a box-drawing table with ANSI colour; when stdout is piped they print plain indented lines with no ANSI codes or box-drawing characters."
    },
    {
      "id": "CLI-OUT-02",
      "criterion": "A non-empty NO_COLOR disables colour and tables even when CLICOLOR_FORCE or FORCE_COLOR is set; an empty NO_COLOR is ignored."
    },
    {
      "id": "CLI-OUT-03",
      "criterion": "CLICOLOR_FORCE or FORCE_COLOR (any value) turns colour and tables on for piped stdout, and CLICOLOR=0 turns them off on a terminal."
    },
    {
      "id": "CLI-OUT-04",
      "criterion": "Text output of status, add, init, pre, snapshot and release --dry-run never contains a schema version string such as `schema v1`."
    },
    {
      "id": "CLI-OUT-05",
      "criterion": "With `--format json`, the status, add, init, pre and snapshot reports on stdout are single JSON objects with camelCase keys and a top-level `schemaVersion`, `command` (the subcommand name) and `dryRun`."
    },
    {
      "id": "CLI-OUT-06",
      "criterion": "When a command fails under `--format json`, stderr ends with a JSON object `{\"schemaVersion\", \"command\", \"error\": {\"code\", \"message\", \"help\", \"path\"}}` and the exit code is 1; `command` is the subcommand that was parsed and `path` is `null` unless the error carries a structured filesystem path.",
      "is_error_case": true
    },
    {
      "id": "CLI-OUT-07",
      "criterion": "When a command fails under text format, stderr shows a diagnostic with an error code and a message, and the exit code is 1.",
      "is_error_case": true
    },
    {
      "id": "CLI-OUT-08",
      "criterion": "Argument parsing errors (unknown flag, missing required argument, invalid value) exit 2 with clap's usage message; every other failure exits 1 and every success exits 0, including --dry-run previews and `release` reporting `Nothing to release.`",
      "is_error_case": true
    },
    {
      "id": "CLI-OUT-09",
      "criterion": "`completions <shell>` and `schema` exit 0 without printing an error or panicking when stdout's reading end is already closed (e.g. piped into a command that exits early); a `--format json` report command's write error in that same situation propagates as `E213` and exits 1."
    },
    {
      "id": "CLI-STATUS-01",
      "criterion": "`callisto status`, with or without a callisto.toml, prints one row per package with its name, current version and planned bump (or `none`), then `<N> package(s) pending`, then a `Diagnostics:` section when any exist."
    },
    {
      "id": "CLI-STATUS-02",
      "criterion": "A package with no changeset of its own that `callisto version` would bump through dependency cascade or a fixed or linked group shows that planned bump in status and counts toward the pending total."
    },
    {
      "id": "CLI-STATUS-03",
      "criterion": "`status --format json` reports `hasChangesets`, `pending` (count of packages with a planned bump), and per package `package`, `currentVersion`, `lastReleasedVersion`, `pendingSeverity` (omitted when no bump is planned), `changedSinceLastTag`, `releaseTrigger` and `pendingChangesets`."
    },
    {
      "id": "CLI-STATUS-04",
      "criterion": "`callisto status` without --check always exits 0; `status --check` exits 0 when no diagnostic is error-level, regardless of pending changesets, and exits 1 when any diagnostic is error-level."
    },
    {
      "id": "CLI-STATUS-05",
      "criterion": "A changeset naming an unknown, ambiguous or invalid package produces an error-level diagnostic naming the changeset file, so `status --check` exits 1; a changeset with no entries at all is an info-level diagnostic and never fails `status --check`; a changeset that fails to parse (blank summary with entries, malformed entry, missing or unclosed frontmatter) produces an error-level diagnostic naming the file and the parse error, so `status --check` exits 1.",
      "is_error_case": true
    },
    {
      "id": "CLI-STATUS-06",
      "criterion": "`status --strict` reports strict-escalatable warnings as errors, so `status --check --strict` exits 1 where `status --check` exits 0.",
      "is_error_case": true
    },
    {
      "id": "CLI-ADD-01",
      "criterion": "`callisto add --package <name>:<severity> --summary <text>` (--package repeatable, bare or qualified names such as `cargo/app`, severity none, patch, minor or major) writes `.changeset/<adjective>-<noun>-<verb>.md`, choosing a name no file in `.changeset` already has and never replacing one, even if another `callisto add` created it a moment earlier, with front matter mapping each package to its severity and the trimmed summary as body, prints `Added changeset: <path>`, and never prompts."
    },
    {
      "id": "CLI-ADD-02",
      "criterion": "`add --format json` prints `{\"schemaVersion\", \"command\": \"add\", \"dryRun\": false, \"path\"}`; with --dry-run it prints `\"dryRun\": true`, the path and the file content, and creates no file or directory."
    },
    {
      "id": "CLI-ADD-03",
      "criterion": "`callisto add` with no --package and a terminal stdin runs a wizard asking, in order, which packages to include, which are major, which remaining are minor (the rest are patch), a non-empty summary unless --summary was given, and a final confirmation; declining the confirmation writes nothing and exits 0. Every wizard prompt and preview line prints to stderr, not stdout."
    },
    {
      "id": "CLI-ADD-04",
      "criterion": "`callisto add` with no --package and a non-terminal stdin exits 1 with error `E214` whose help names `callisto add --package <name>:<severity>`.",
      "is_error_case": true
    },
    {
      "id": "CLI-ADD-05",
      "criterion": "`add --package` without --summary, or with a whitespace-only summary, exits 1 naming --summary and writes nothing.",
      "is_error_case": true
    },
    {
      "id": "CLI-ADD-06",
      "criterion": "A --package value missing `:severity`, with an unknown severity, or naming a package not in the workspace exits 1 and writes nothing; an unknown package name reports E102, and a bare name ambiguous across ecosystems reports E103 listing the qualified candidates.",
      "is_error_case": true
    },
    {
      "id": "CLI-INIT-01",
      "criterion": "Before any question, `callisto init` prints `Detected:` with the ecosystems, the origin remote URL, and each package's qualified id, version, last tag, and executable names for executable-producing packages. Artifact selection includes only supported Cargo binary targets."
    },
    {
      "id": "CLI-INIT-02",
      "criterion": "Interactive init asks only: versioning (independent or fixed); whether to ship Cargo binaries as GitHub release assets, only when a supported Cargo binary target exists; the product package, only when more than one Cargo package produces a binary; the forge repository, pre-filled from origin; comma-separated target triples; whether to generate a workflow (default no); and whether to write callisto.toml (default yes)."
    },
    {
      "id": "CLI-INIT-03",
      "criterion": "A supplied flag (--versioning, --artifact-target, --product-package, --forge-repository, --workflow, --no-workflow) skips its question, and declining the final write question writes no file."
    },
    {
      "id": "CLI-INIT-04",
      "criterion": "The written callisto.toml starts with `# callisto configuration` and contains only answered intent: a `[[fixed-group]]` named `all` listing every non-platform package for fixed versioning, a `[[package]]` `tag-template` for each package whose existing tags follow a non-default convention, and, when shipping binaries, `publish-to` with `github-release` on the selected Cargo product plus a `[release]` table with `product-package`, `forge-repository` and one `[[release.artifact]]` per target and Cargo binary."
    },
    {
      "id": "CLI-INIT-05",
      "criterion": "Tag detection matches each package's tags against its `{display id}@{version}` default, `{name}-v{version}`, `{name}-{version}` and `v{version}`, and writes the single matching non-default convention as that package's tag-template."
    },
    {
      "id": "CLI-INIT-06",
      "criterion": "init exits 1 without writing when a package matches more than one tag convention (listing each with its tags) or when more than one package matches `v{version}`.",
      "is_error_case": true
    },
    {
      "id": "CLI-INIT-07",
      "criterion": "After the config, init prints the first-release preview that `callisto release --dry-run` would show under it, or `No commits yet: commit, then run \\`callisto release --dry-run\\` to preview the first release.` when HEAD has no commit."
    },
    {
      "id": "CLI-INIT-08",
      "criterion": "A successful init writes callisto.toml and creates .changeset/README.md only when it does not already exist."
    },
    {
      "id": "CLI-INIT-09",
      "criterion": "init exits 1 without writing when callisto.toml already exists or when the directory is not inside a Git repository, each with a help line naming the fix. With no `origin` remote configured, init instead writes callisto.toml, skips the workflow and shipping-binaries questions, and emits an `init-origin-missing` warning diagnostic; `--workflow` or `--artifact-target` without `origin` exits 1 naming the fix, and `callisto release` refuses later.",
      "is_error_case": true
    },
    {
      "id": "CLI-INIT-10",
      "criterion": "With a non-terminal stdin and no --yes, init exits 1 with `E240` naming --yes and every other missing flag; with --yes it exits 1 with `E241` naming each missing flag: --versioning always, --forge-repository when --artifact-target is given, and --product-package when --artifact-target is given and more than one supported Cargo package produces a binary.",
      "is_error_case": true
    },
    {
      "id": "CLI-INIT-11",
      "criterion": "With --yes, omitting --artifact-target writes no `[release]` table; --artifact-target is repeatable and comma-separated, and --workflow with --no-workflow exits 1 with `E242` before writing.",
      "is_error_case": true
    },
    {
      "id": "CLI-INIT-12",
      "criterion": "init exits 1 without writing for an empty or repeated target triple, --artifact-target when no supported Cargo package produces a binary, a --product-package that is absent or not a supported Cargo binary producer, a --forge-repository that is not `owner/repo` or differs from origin's GitHub repository, or --forge-repository or --product-package given without --artifact-target. An npm `bin` or Python `[project.scripts]` product selected for an artifact fails with a typed unsupported-builder diagnostic; registry-only npm and PyPI releases remain valid.",
      "is_error_case": true
    },
    {
      "id": "CLI-INIT-13",
      "criterion": "`init --format json` writes the human-readable detection, config and preview to stderr and a report `{schemaVersion, command: \"init\", dryRun, initialized, configPath, config, files}` (plus `diagnostics` when any) to stdout; with --dry-run `dryRun` is true, `initialized` is false, `files` lists every file that would be written, and no file is written."
    },
    {
      "id": "CLI-INIT-14",
      "criterion": "When `.changeset/config.json` exists and declares `fixed`, `linked`, `ignore`, `access`, `baseBranch`, or `updateInternalDependencies` -- none of which callisto translates -- init emits a `changesets-config-key-dropped` warning diagnostic per such key present, naming `[[fixed-group]]` as `fixed`'s callisto.toml equivalent and stating no equivalent exists for the others."
    },
    {
      "id": "CLI-INIT-15",
      "criterion": "When init fails to write callisto.toml, .changeset/README.md, or a generated workflow file, it exits 1 with E278 naming the exact path it failed to write.",
      "is_error_case": true
    },
    {
      "id": "CLI-INIT-16",
      "criterion": "Cargo binary detection includes every explicit `[[bin]]` name (or path-derived name when omitted), `src/main.rs`, `src/bin/<name>.rs`, and `src/bin/<name>/main.rs`, de-duplicates names, and honors `package.autobins = false` for automatic targets. npm `bin` and Python `[project.scripts]` are detected as executables but are rejected as GitHub artifact builders before init writes files."
    },
    {
      "id": "CLI-WF-01",
      "criterion": "A workflow is written to .github/workflows/callisto-release.yml only when --workflow is given or the interactive workflow question is answered yes; after writing, init prints that merging to the default branch publishes and advises requiring pull requests and reviews on it."
    },
    {
      "id": "CLI-WF-02",
      "criterion": "init never overwrites an existing .github/workflows/callisto-release.yml: when a workflow is requested and the file exists, init exits 1 before writing any file.",
      "is_error_case": true
    },
    {
      "id": "CLI-WF-03",
      "criterion": "Without artifact slots or platform packages, the generated workflow triggers on push to the detected default branch (local `origin/HEAD`, else a live query of `origin`, else the checked-out branch, else `main`) and has two jobs: `version-pr` running callisto-action with `mode: version-pr` and that same `branch`, and `release` running it with `mode: release` and a token secret per detected ecosystem (CARGO_REGISTRY_TOKEN, NPM_TOKEN with NPM_CONFIG_PROVENANCE, PYPI_TOKEN) plus GH_TOKEN. These secrets are scoped to the release action step; that action configures npm and Twine native auth only for publishing, supports Bun's token environment, and withholds registry credentials from the Python build backend. Native package-manager publish hooks retain their normal package-owner-defined behavior. When a Python ecosystem is detected, the `release` job installs pinned `build` and `twine` into a venv on the PATH before the release step, with no secrets. init's human-readable output names which of those sources resolved the branch."
    },
    {
      "id": "CLI-WF-04",
      "criterion": "When binaries ship as artifact slots or the workspace has napi platform packages, the generated workflow has `version-pr`, `plan` (runs `callisto release plan --from-release-commit` when the pushed commit adds or modifies .callisto/release-decision.json), `build` (a matrix from napi targets and artifact slots), `build-python` (only when the plan publishes a Python package; builds its sdist and wheel with no credentials) and `execute` (installs a pinned `twine` into a venv on the PATH when the plan publishes a Python package, runs `callisto release artifact-manifest`, sealing those files, and `callisto release execute`) jobs. Registry secrets are scoped to the execute publishing step, never plan or build; npm and Twine receive native auth configuration only during execution, and registry credentials are withheld from Python build subprocesses. Native package-manager publish hooks retain their normal package-owner-defined behavior. The build matrix and napi artifact placement cover only the packages in the release intent, so an unrelated napi addon adds no build and cannot fail the plan."
    },
    {
      "id": "CLI-WF-05",
      "criterion": "Every callisto-action reference in a generated workflow is pinned to the commit SHA of the `callisto@<cli version>` tag, and init exits 1 when that tag cannot be resolved.",
      "is_error_case": true
    },
    {
      "id": "CLI-WF-06",
      "criterion": "For a workspace with maturin platform targets, or platform packages without napi targets, init prints `Skipping GitHub Actions workflow generation: <reason>.`, records a warning diagnostic in the JSON report, and exits 1 instead when --workflow was given.",
      "is_error_case": true
    },
    {
      "id": "CLI-WF-07",
      "criterion": "callisto-action accepts `mode: version-pr` (default; creates or updates the release PR and outputs `hasChangesets`) and `mode: release` (runs `callisto --format json release` and outputs `published` and `publishedPackages`); any other mode fails the step.",
      "is_error_case": true
    },
    {
      "id": "CLI-PRE-01",
      "criterion": "`callisto pre enter <tag>` writes .changeset/pre.json with mode `pre`, the tag and each package's initial version; `callisto pre exit` sets its mode to `exit`. When pre.json already exists with mode `exit`, `pre enter` resumes the cycle: it keeps the existing `initialVersions` and `changesets` and only updates `mode` to `pre` and `tag` to the new value."
    },
    {
      "id": "CLI-PRE-02",
      "criterion": "`pre enter` while pre.json's mode is `pre` exits 1 naming the next step; `pre exit` after prerelease mode was already exited exits 1 naming the next step; `pre exit` with no .changeset/pre.json exits 1 naming `callisto pre enter <tag>`.",
      "is_error_case": true
    },
    {
      "id": "CLI-SNAP-01",
      "criterion": "`callisto snapshot --tag <tag>` sets each SemVer package's manifest version to `0.0.0-<tag>-<short HEAD sha>` and each PEP 440 package's to `0.0.0.dev0+<tag>.<short HEAD sha>`, prints each `from → to`, and leaves changesets in place."
    },
    {
      "id": "CLI-COMP-01",
      "criterion": "`callisto completions <shell>` prints a completion script for bash, elvish, fish, powershell or zsh and exits 0."
    },
    {
      "id": "CLI-SCHEMA-01",
      "criterion": "`callisto schema` prints the StatusReport JSON Schema; `--type` is a fixed value enum selecting another report type, and an unrecognized value is a clap usage error (exit 2) listing the supported values. Schemas describe the selected payload's serialized values, including string versions, package identities, commit SHAs, repository slugs and digests, not their internal Rust representation. Report payload schemas are distinct from command/dryRun stdout metadata; the release-receipt schema describes the durable receipt file. Native value validity remains enforced by domain readers."
    }
  ],
  "spec_file_path": "docs/specs/cli.json"
}

{
  "id": "SPEC-MATRIX",
  "purpose": "`callisto matrix` reads native build targets and runtime-version constraints from workspace manifests and prints one deterministic report that CI uses as its build matrix.",
  "scope": "The hidden `callisto matrix [--package <name>]` command, its JSON and text output, and its errors and warnings.",
  "non_goals": [
    ".NET and Java target or runtime discovery.",
    "Validating or expanding engines.node and requires-python ranges; they pass through verbatim.",
    "Inferring maturin targets from manylinux tags or any source other than the declared target fields.",
    "Generating CI workflow YAML."
  ],
  "api_surface": [
    {
      "name": "callisto matrix",
      "signature": "callisto [--format text|json] matrix [--package <name>]",
      "description": "Prints a MatrixReport with schemaVersion, platformTargets and runtimeVersions keyed by package id, plus diagnostics when any exist. Hidden from --help.",
      "error_conditions": [
        "E102: --package names no registered package.",
        "E103: bare --package name matches packages in more than one ecosystem.",
        "E118: one package declares both napi.targets and [tool.maturin].targets.",
        "E203: a package with napi or maturin targets is also a cargo [[release.artifact]] package.",
        "E204: a napi package's addon crate does not resolve to exactly one workspace crate.",
        "Malformed package.json or pyproject.toml, or a target or runtime field of the wrong type."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "MX-DISC-01",
      "criterion": "A package whose package.json declares napi.targets gets a platformTargets entry with kind \"napi\" and source \"napi.targets\"; one whose pyproject.toml declares [tool.maturin].targets gets kind \"maturin\" and source \"[tool.maturin].targets\"."
    },
    {
      "id": "MX-DISC-02",
      "criterion": "A declared but empty target array yields an entry with an empty targets list, while a package declaring neither field has no platformTargets entry."
    },
    {
      "id": "MX-DISC-03",
      "criterion": "engines.node in package.json yields a runtimeVersions item {\"ecosystem\":\"npm\",\"field\":\"engines.node\"} and requires-python in pyproject.toml yields {\"ecosystem\":\"python\",\"field\":\"requires-python\"}, each with range set to the raw manifest string; a package with both lists npm first, and a package with neither has no runtimeVersions entry."
    },
    {
      "id": "MX-DISC-04",
      "criterion": "Each recognised triple yields platform, arch, abi, hostRunner and useCross from one shared table, so napi and maturin packages declaring the same triple get identical values for those fields."
    },
    {
      "id": "MX-DISC-05",
      "criterion": "abi is a string for linux triples (for example \"gnu\", \"musl\", \"gnueabihf\") and JSON null for darwin, win32, freebsd, android and wasm32 triples."
    },
    {
      "id": "MX-DISC-06",
      "criterion": "hostRunner is \"macos-latest\" for aarch64-apple-darwin, \"macos-13\" for x86_64-apple-darwin, \"windows-latest\" for windows triples and \"ubuntu-latest\" for all others; useCross is true for every ubuntu-hosted triple except x86_64-unknown-linux-gnu and the two wasm32 triples."
    },
    {
      "id": "MX-DISC-07",
      "criterion": "For napi and maturin targets, artifactName is the package's bare name with every \"/\" replaced by \"-\", then \"-<platform>-<arch>\", then \"-<abi>\" only when abi is non-null (for example \"addon-linux-x64-gnu\")."
    },
    {
      "id": "MX-DISC-08",
      "criterion": "A napi target carries no manifestPath when a workspace napi addon crate (a cdylib depending on napi) has its Cargo.toml in the package's own directory; otherwise manifestPath is the workspace-relative Cargo.toml of the one addon crate whose lib name equals napi.binaryName."
    },
    {
      "id": "MX-DISC-09",
      "criterion": "The binary name is napi.binaryName, else napi.name, else \"index\", and a crate's lib name is its [lib] name, else its package name, with \"-\" replaced by \"_\"."
    },
    {
      "id": "MX-DISC-10",
      "criterion": "Each cargo [[release.artifact]] entry naming a workspace cargo package adds a target to a platformTargets entry with kind \"cargo\" and source \"[[release.artifact]]\", whose artifactName is the entry's asset-name and whose packageDir is the cargo manifest's directory."
    },
    {
      "id": "MX-DISC-11",
      "criterion": "`--package <name>` limits platformTargets and runtimeVersions to the one package it resolves to; a bare name resolves only when it matches exactly one package, and a qualified id such as `cargo/foo` selects the promoted package in that ecosystem."
    },
    {
      "id": "MX-OUT-01",
      "criterion": "platformTargets and runtimeVersions are keyed by the package's display id: the bare name, or `<ecosystem>/<name>` when packages in two ecosystems share that name, so a cargo crate and an npm package named alike get separate entries."
    },
    {
      "id": "MX-OUT-02",
      "criterion": "Map keys are in lexicographic order, and each entry's targets are sorted by triple (cargo targets then by artifactName)."
    },
    {
      "id": "MX-OUT-03",
      "criterion": "`--format json` prints pretty JSON with no \"command\" key; an empty workspace prints exactly {\"schemaVersion\":1,\"platformTargets\":{},\"runtimeVersions\":{}} and exits 0, and the diagnostics key appears only when there is at least one diagnostic."
    },
    {
      "id": "MX-OUT-04",
      "criterion": "Each target object has triple, platform, arch, abi, hostRunner, useCross, artifactName, packageDir and packageName, plus manifestPath only when set."
    },
    {
      "id": "MX-OUT-05",
      "criterion": "`--format text` and a bare `callisto matrix` print the same non-JSON table and exit 0."
    },
    {
      "id": "MX-ERR-01",
      "criterion": "A triple outside the recognised table is left out of targets and reported as a warning with code \"unrecognised-platform-triple\"; the command still exits 0, and a cargo entry left with no targets is dropped.",
      "is_error_case": true
    },
    {
      "id": "MX-ERR-02",
      "criterion": "A triple repeated within one package's target list keeps its first occurrence and reports a warning with code \"duplicate-platform-triple\".",
      "is_error_case": true
    },
    {
      "id": "MX-ERR-03",
      "criterion": "A cargo [[release.artifact]] whose package is not a workspace cargo package produces a warning with code \"unknown-package\" naming the package and asset, adds no entry, and the command exits 0.",
      "is_error_case": true
    },
    {
      "id": "MX-ERR-04",
      "criterion": "A napi package with at least one recognised target whose binary name matches zero or several addon crates fails with E204, naming the binary name and listing the matching crates, or every addon crate when none match.",
      "is_error_case": true
    },
    {
      "id": "MX-ERR-05",
      "criterion": "A package declaring both napi.targets and [tool.maturin].targets fails with E118 naming the package and both fields; a package with napi or maturin targets that is also a cargo [[release.artifact]] package fails with E203.",
      "is_error_case": true
    },
    {
      "id": "MX-ERR-06",
      "criterion": "A napi.targets or [tool.maturin].targets value that is not an array of strings, an engines.node or requires-python value that is not a string, or an unparsable manifest belonging to a registered package exits 1 with an error naming the manifest path.",
      "is_error_case": true
    },
    {
      "id": "MX-ERR-07",
      "criterion": "`--package` naming no registered package exits 1 with E102 naming it, and a bare name matching packages in several ecosystems exits 1 with E103 listing the qualified candidates.",
      "is_error_case": true
    },
    {
      "id": "MX-ERR-08",
      "criterion": "Every failing run prints no MatrixReport JSON on stdout.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/matrix.json"
}

